<header class="admin-page-heading"><div><p class="eyebrow">内容运营</p><h1>自定义标签</h1><p class="muted">维护可供前台主题读取的短文本；标签标识与 PbootCMS 的 {label:名称} 对应。</p></div><a class="layui-btn" href="/admin/labels/new"><i class="fa fa-plus" aria-hidden="true"></i> 新建标签</a></header>
<section class="panel"><?php if (! $labels): ?><p class="muted">暂无自定义标签。</p><?php else: ?><div class="table-wrap"><table><thead><tr><th>标识</th><th>说明</th><th>内容预览</th><th>操作</th></tr></thead><tbody>
<?php foreach ($labels as $label): ?><tr><td><code>{label:<?= \FangdaysCMS\Cms\View::e($label['name']) ?>}</code></td><td><?= \FangdaysCMS\Cms\View::e($label['description']) ?></td><td><?= \FangdaysCMS\Cms\View::e(mb_strimwidth($label['value'], 0, 80, '…')) ?></td><td class="actions"><a href="/admin/labels/<?= (int) $label['id'] ?>/edit">编辑</a><form method="post" action="/admin/labels/<?= (int) $label['id'] ?>/delete" class="inline-form" onsubmit="return confirm('删除此标签？')"><?= \FangdaysCMS\Cms\View::csrf() ?><button class="link-button danger" type="submit">删除</button></form></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section>
